function ConnectorMini({data}){const count=data.pinout?.length||2,circular=['Circular','JR'].includes(data.familia);const dots=Array.from({length:count},(_,i)=>{let x,y;if(circular){const inner=count>8&&i<6,n=inner?6:Math.max(1,count-(count>8?6:0)),j=inner?i:i-(count>8?6:0),r=inner?11:count>8?23:18,a=-Math.PI/2+j*2*Math.PI/n;x=50+Math.cos(a)*r;y=48+Math.sin(a)*r}else{const cols=Math.min(count,5),rows=Math.ceil(count/cols);x=28+(i%cols)*(44/Math.max(1,cols-1));y=48+(Math.floor(i/cols)-(rows-1)/2)*13}return <g key={i}><circle cx={x} cy={y} r="3.5" fill={data.pin_colors?.[i+1]||'#9aa9b0'} stroke="#eaf0f2" strokeWidth=".7"/><text x={x} y={y+1.7} textAnchor="middle" fontSize="3.6" fill="#101820">{i+1}</text></g>});return <svg viewBox="0 0 100 96" role="img" aria-label={`Vector ${data.familia||'Circular'} de ${data.label}`}><rect x="1" y="1" width="98" height="94" rx="6" fill="#0b1319" stroke="#344955"/><text x="50" y="10" textAnchor="middle" fontSize="5.5" fill="#aab9c0">{data.modelo||data.familia||'CONECTOR'}</text>{circular?<><circle cx="50" cy="51" r="34" fill="#252f35" stroke="#aab8be" strokeWidth="2.5"/><circle cx="50" cy="51" r="29" fill="#111a20" stroke="#576972" strokeWidth="1.4"/><path d="M46 17h8v5h-8z" fill="#aab8be"/></>:<><rect x="16" y="22" width="68" height="58" rx={data.familia==='RJ45'?4:9} fill="#273239" stroke="#aab8be" strokeWidth="2.5"/><rect x="21" y="27" width="58" height="48" rx="5" fill="#111a20" stroke="#576972"/></>}{dots}<text x="50" y="90" textAnchor="middle" fontSize="5" fill="#91a1a8">VISTA {data.genero==='Macho'?'POSTERIOR':'FRONTAL'}</text></svg>}
function SchematicPinNode({data}){return <div className="schematic-connector-node" onContextMenu={event=>{event.preventDefault();data.onContextMenu?.(event,data)}} onDoubleClick={()=>data.onView?.(data)}><div className="schematic-node-heading"><strong>{data.label}</strong><small>{data.code} · {data.pinout.length} señales</small></div><div className="schematic-node-content"><div className="schematic-node-pins">{data.pinout.map((pin,i)=><div className={`schematic-pin-row ${data.selectedPins?.includes(String(i+1))?'pin-focused':''}`} key={i}><Handle type="target" position={Position.Left} id={`${i+1}`} className="schematic-handle"/><span className="schematic-pin-number">{String(i+1).padStart(2,'0')}</span><i className="schematic-pin-color" style={{background:data.pin_colors?.[i+1]||'#788a93'}}/><span className="schematic-pin-label"><b>{pin||`PIN_${i+1}`}</b>{data.pinRoutes?.[i+1]?.map((route,j)=><small key={j} title={route}>{route}</small>)}</span><Handle type="source" position={Position.Right} id={`${i+1}`} className="schematic-handle"/></div>)}</div></div></div>}
function CrimpNode({data}){const color=data.color||'#4388d1';return <div className="harness-crimp-node" title="Crimp: une conductores en este punto"><Handle type="target" position={Position.Left} id="1"/><svg className="crimp-glyph" viewBox="0 0 72 22" aria-hidden="true"><path d="M2 6h68v10H2z" fill="#c7d0d5" stroke="#465760" strokeWidth="1.5"/><path d="M7 8h58v6H7z" fill="#e9eef0"/><rect x="25" y="4" width="22" height="14" rx="4" fill={color} stroke="#263b46" strokeWidth="1.5"/><path d="M30 6v10M42 6v10" stroke="#fff" strokeOpacity=".75" strokeWidth="1.2"/></svg><strong>{data.label||'CRIMP'}</strong><Handle type="source" position={Position.Right} id="1"/></div>}
const nodeTypes={component:PinNode,splice:CrimpNode};const schematicNodeTypes={schematic:SchematicPinNode,splice:CrimpNode,footprint:FootprintNode};function CableEdge({id,source,sourceHandle,target,targetHandle,sourceX,sourceY,targetX,targetY,sourcePosition,targetPosition,style,markerEnd,data}){
  const[chooserOpen,setChooserOpen]=useState(false);
  const flowEdges=useEdges();
  const sourceNode=useInternalNode(source);
  const targetNode=useInternalNode(target);
  const hasExplicitBundle=!!data?.grupo_cable;
  const pairKey=[source,target].sort().join('↔');
  const bundle=hasExplicitBundle?flowEdges.filter(edge=>edge.type==='cable'&&edge.data?.grupo_cable===data.grupo_cable&&[edge.source,edge.target].sort().join('↔')===pairKey):flowEdges.filter(edge=>edge.id===id);
  const bundleIndex=Math.max(0,bundle.findIndex(edge=>edge.id===id));
  const count=bundle.length||1;
  const handlePoint=(node,type,handleId,fallback)=>{
    const handle=(node?.internals?.handleBounds?.[type]||[]).find(item=>String(item.id||'1')===String(handleId||'1'));
    if(!node||!handle)return fallback;
    return{x:node.internals.positionAbsolute.x+handle.x+handle.width/2,y:node.internals.positionAbsolute.y+handle.y+handle.height/2};
  };
  const members=bundle.map(edge=>{
    const sourceIsNode=edge.source===source;
    const from=sourceIsNode?handlePoint(sourceNode,'source',edge.sourceHandle,{x:sourceX,y:sourceY}):handlePoint(targetNode,'target',edge.targetHandle,{x:sourceX,y:sourceY});
    const to=sourceIsNode?handlePoint(targetNode,'target',edge.targetHandle,{x:targetX,y:targetY}):handlePoint(sourceNode,'source',edge.sourceHandle,{x:targetX,y:targetY});
    return{edge,from,to};
  });
  const avg=(items,key)=>items.reduce((sum,item)=>sum+item[key],0)/Math.max(1,items.length);
  const centerY=(avg(members.map(item=>item.from),'y')+avg(members.map(item=>item.to),'y'))/2;
  const direction=targetX>=sourceX?1:-1;
  const gap=Math.max(4,Math.min(36,Math.abs(targetX-sourceX)*.12));
  const branchStartX=sourceX+direction*gap,branchEndX=targetX-direction*gap;
  const grouped=hasExplicitBundle&&count>1;
  const offset=grouped?(bundleIndex-(count-1)/2)*6:0;
  const laneY=grouped?centerY+offset:(sourceY+targetY)/2;
  const labelX=(sourceX+targetX)/2;
  const conductorPath=`M ${sourceX} ${sourceY} H ${branchStartX} V ${laneY} H ${branchEndX} V ${targetY} H ${targetX}`;
  const bundleStartX=members.reduce((sum,item)=>sum+item.from.x,0)/Math.max(1,members.length)+direction*gap;
  const bundleEndX=members.reduce((sum,item)=>sum+item.to.x,0)/Math.max(1,members.length)-direction*gap;
  const bundlePath=`M ${bundleStartX} ${centerY} H ${bundleEndX}`;
  const fanPath=`M ${sourceX} ${sourceY} H ${branchStartX} V ${centerY} H ${bundleStartX} M ${bundleEndX} ${centerY} H ${branchEndX} V ${targetY} H ${targetX}`;
  const wireState=flowEdges.find(edge=>edge.id===id);
  const wireActive=!!(wireState?.selected||data?.highlighted);
  const bundleActive=members.some(item=>item.edge.selected||item.edge.data?.highlighted);
  const hasSelection=flowEdges.some(edge=>edge.selected||edge.data?.highlighted);
  const jacketOpacity=hasSelection&&!bundleActive?.28:1;
  const color=style?.stroke||'#38bdf8';
  const bundleMarker=grouped&&bundleIndex===0;
  const explicitLabel=String(data?.etiqueta||'').trim();
  const sourceName=sourceNode?.data?.label||source,targetName=targetNode?.data?.label||target;
  const sourceRef=String(sourceName).split(' · ')[0],targetRef=String(targetName).split(' · ')[0];
  const signalLabel=explicitLabel&&!/^\d+\s*AWG$/i.test(explicitLabel)?explicitLabel:'Conductor';
  const routeTag=`${signalLabel} · ${sourceRef}-${sourceHandle||1}→${targetRef}-${targetHandle||1}`;
  const groupTag=`${data?.grupo_cable||'MAZO'} · ${count} vías`;
  const showRouteLabel=data?.labelsVisible===false?false:(grouped?wireActive:!!routeTag);
  const routeY=(grouped?laneY:(sourceY+targetY)/2)+Number(data?.labelOffset||0);
  const onChooseWire=wireId=>data?.onSelectBundleWire?.(wireId);
  return <>
    {bundleMarker&&<BaseEdge id={id+'-bundle-hit'} path={bundlePath} interactionWidth={26} style={{stroke:'transparent',strokeWidth:1,pointerEvents:'stroke'}}/>}
    {bundleMarker&&<><BaseEdge id={id+'-bundle-core'} path={bundlePath} style={{stroke:'#18232b',strokeWidth:15,opacity:jacketOpacity,strokeLinecap:'round'}}/><BaseEdge id={id+'-bundle-wrap'} path={bundlePath} style={{stroke:data?.color_funda||'#ff1200',strokeWidth:10,opacity:jacketOpacity,strokeLinecap:'round'}}/></>}
    {grouped&&!wireActive&&<><BaseEdge id={id+'-fan-halo'} path={fanPath} style={{stroke:'#f8f7f0',strokeWidth:4.6,strokeLinecap:'round',strokeLinejoin:'round'}}/><BaseEdge id={id+'-fan'} path={fanPath} style={{stroke:color,strokeWidth:2.2,strokeLinecap:'round',strokeLinejoin:'round'}}/></>}
    {(!grouped||wireActive)&&<><BaseEdge id={id+'-wire-halo'} path={conductorPath} style={{stroke:grouped?'#f8f7f0':'#080d12',strokeWidth:grouped?5:Math.max(2,(style?.strokeWidth||2)+1.5),strokeLinecap:'round',strokeLinejoin:'round'}}/><BaseEdge id={id} path={conductorPath} style={{...style,stroke:color,strokeWidth:grouped?2.8:Math.max(1.2,(style?.strokeWidth||2)*.7),strokeLinecap:'round',strokeLinejoin:'round'}} markerEnd={grouped?undefined:markerEnd}/></>}
    {bundleMarker&&<EdgeLabelRenderer><div className="bundle-label-wrap" style={{transform:`translate(-50%,-50%) translate(${labelX}px,${centerY-20}px)`,opacity:jacketOpacity*(data?.labelOpacity??1),display:data?.labelsVisible===false?'none':undefined}}><button type="button" className="cable-edge-label bundle-group-label nopan" onClick={event=>{event.stopPropagation();setChooserOpen(value=>!value)}} title="Selecciona una vía para ver su recorrido individual">{groupTag}</button>{chooserOpen&&<div className="bundle-wire-chooser nopan">{bundle.map(item=>{const forward=item.source===source;const fromPin=forward?item.sourceHandle:item.targetHandle;const toPin=forward?item.targetHandle:item.sourceHandle;const signal=String(item.data?.etiqueta||`Pin ${fromPin||1}`).trim();return <button type="button" key={item.id} onClick={event=>{event.stopPropagation();onChooseWire(item.id);setChooserOpen(false)}}><i style={{background:item.data?.color||'#ff1200'}}/><span>{signal}</span><small>{sourceRef}-{fromPin||1} → {targetRef}-{toPin||1}</small></button>})}</div>}</div></EdgeLabelRenderer>}
    {showRouteLabel&&<EdgeLabelRenderer><div className="cable-edge-label cable-edge-route-label" title={`${signalLabel} · ${sourceName} pin ${sourceHandle||1} → ${targetName} pin ${targetHandle||1}`} style={{transform:`translate(-50%,-50%) translate(${labelX}px,${routeY}px)`,borderColor:color,opacity:data?.labelOpacity??1}}>{routeTag}{data?.longitud_mm?` · ${data.longitud_mm} mm`:''}</div></EdgeLabelRenderer>}
  </>;
}
