function Modal({close,create}){const[name,setName]=useState(''),[desc,setDesc]=useState('');return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><section className="modal-card"><div className="modal-head"><div><div className="eyebrow">NUEVO ESPACIO DE TRABAJO</div><h2>Crear arnés</h2></div><button className="icon-button" onClick={close}><X size={18}/></button></div><label className="field-label">Nombre del proyecto</label><input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder="Ej. Arnés de control · Prototipo B"/><label className="field-label">Descripción <span>OPCIONAL</span></label><textarea rows="3" value={desc} onChange={e=>setDesc(e.target.value)} placeholder="Objetivo, equipo asociado, notas de diseño..."/><div className="modal-actions"><button className="btn-quiet" onClick={close}>Cancelar</button><button disabled={!name.trim()} className="btn-primary" onClick={()=>create(name,desc)}>Crear proyecto <ArrowLeft size={15} className="arrow-forward"/></button></div></section></div>}
function Card({p,i,open}){return <button className="project-card" onClick={open}><div className={`project-thumb pattern-${i%4}`}><div className="thumb-grid"/><div className="schematic-line line-a"/><div className="schematic-line line-b"/><div className="schematic-node node-a"/><div className="schematic-node node-b"/><div className="schematic-node node-c"/><div className="thumb-code">HL–{String(p.id).padStart(3,'0')}</div><div className={`project-status ${status[p.estado]}`}><i/>{p.estado}</div></div><div className="project-card-body"><div className="project-title-row"><strong>{p.nombre}</strong><span>···</span></div><p>{p.descripcion||'Sin descripción del proyecto.'}</p><div className="project-card-meta"><span><Clock3 size={13}/>{new Date(p.fecha_creacion).toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'})}</span><span><Layers3 size={13}/> Diseño eléctrico</span></div><div className="project-progress"><i style={{width:p.estado==='Terminado'?'100%':p.estado==='En progreso'?'48%':'8%'}}/></div></div></button>}
function Dashboard({user,users,projects,open,create,logout}){const[filter,setFilter]=useState('Todos'),[query,setQuery]=useState(''),[modal,setModal]=useState(false);const shown=projects.filter(p=>(filter==='Todos'||p.estado===filter)&&`${p.nombre} ${p.descripcion}`.toLowerCase().includes(query.toLowerCase()));const active=projects.filter(p=>p.estado==='En progreso').length,done=projects.filter(p=>p.estado==='Terminado').length;const submit=async(n,d)=>{await create(n,d);setModal(false)};return <div className="app-shell"><aside className="sidebar"><div className="brand"><div className="brand-mark"><Cable size={19}/></div><div><strong>Harness<span>Lab</span></strong><small>DESIGN SYSTEM</small></div></div><div className="workspace-tag"><i/> LABORATORIO LOCAL</div><div className="side-section-label">ESPACIO DE TRABAJO</div><button className="side-link active"><Layers3 size={17}/> Proyectos <span>{projects.length}</span></button><button className="side-link" onClick={()=>document.getElementById('catalog')?.scrollIntoView({behavior:'smooth'})}><Cpu size={17}/> Catálogo</button><div className="side-bottom"><div className="lab-status"><div><i/>Servidor local</div><small>Sincronización activa</small><div className="status-wave">{Array.from({length:17},(_,i)=><i key={i}/>)}</div></div><button className="user-menu" onClick={logout}><Avatar user={user}/><span><strong>{user.nombre}</strong><small>{user.rol}</small></span><LogOut size={15}/></button></div></aside><main className="main-area"><header className="topbar"><div>Espacio de trabajo <b>/</b> <strong>Proyectos</strong></div><div className="topbar-right"><span className="sync-badge"><Radio size={13}/> EN VIVO</span><div className="online-avatars">{users.slice(0,3).map(u=><Avatar key={u.id} user={u} className="tiny-avatar"/>)}</div><Avatar user={user} className="top-user"/></div></header><div className="page-content"><div className="welcome-row"><div><div className="eyebrow">CENTRO DE INGENIERÍA / {new Date().toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'}).toUpperCase()}</div><h1>Proyectos <span className="heading-count">{String(projects.length).padStart(2,'0')}</span></h1><p>Diseña y coordina el ensamblaje de tus arneses eléctricos.</p></div>{user.rol!=='visor'&&<button className="btn-primary" onClick={()=>setModal(true)}><Plus size={17}/> Nuevo proyecto</button>}</div><div className="metric-grid"><div className="metric-card"><div className="metric-label"><span className="metric-icon blue"><Layers3 size={16}/></span> PROYECTOS TOTALES</div><div className="metric-value">{String(projects.length).padStart(2,'0')}<small> proyectos</small></div><div className="metric-bottom">En este espacio</div></div><div className="metric-card"><div className="metric-label"><span className="metric-icon amber"><Activity size={16}/></span> EN EJECUCIÓN</div><div className="metric-value">{String(active).padStart(2,'0')}<small> activos</small></div><div className="metric-bottom">Trabajo en curso</div></div><div className="metric-card"><div className="metric-label"><span className="metric-icon green"><Check size={16}/></span> COMPLETADOS</div><div className="metric-value">{String(done).padStart(2,'0')}<small> finalizados</small></div><div className="metric-bottom">Listos para producción</div></div><div className="metric-card"><div className="metric-label"><span className="metric-icon violet"><Users size={16}/></span> EQUIPO DISPONIBLE</div><div className="team-row">{users.map(u=><Avatar key={u.id} user={u} className="team-avatar"/>)}</div><div className="metric-bottom"><i/> {users.length} perfiles en laboratorio</div></div></div><div className="section-toolbar"><div className="filter-tabs">{['Todos','En progreso','No empezado','Terminado'].map(f=><button key={f} className={filter===f?'filter-active':''} onClick={()=>setFilter(f)}>{f}<span>{f==='Todos'?projects.length:projects.filter(p=>p.estado===f).length}</span></button>)}</div><div className="toolbar-actions"><div className="search-box"><Search size={15}/><input placeholder="Buscar proyectos..." value={query} onChange={e=>setQuery(e.target.value)}/><kbd>⌘ K</kbd></div><button className="icon-button bordered"><SlidersHorizontal size={16}/></button></div></div><div className="project-grid">{shown.map((p,i)=><Card key={p.id} p={p} i={i} open={()=>open(p)}/>)}{!shown.length&&<div className="empty-state"><strong>{projects.length?'Sin resultados':'Tu espacio está listo'}</strong><p>{projects.length?'Prueba otro filtro.':'Crea tu primer proyecto para comenzar.'}</p>{!projects.length&&user.rol!=='visor'&&<button className="btn-primary" onClick={()=>setModal(true)}><Plus size={16}/> Crear proyecto</button>}</div>}</div><div className="catalog-strip" id="catalog"><Cpu size={16}/><div><strong>Catálogo de componentes</strong><small>Conectores, sensores, protecciones y empalmes</small></div><span>4 COMPONENTES</span><span>⌄</span></div><footer className="footer"><span>HARNESS LAB · SISTEMA DE DISEÑO DE ARNÉSES</span><span>BUILD 0.9.4 · LOCAL NETWORK</span></footer></div>{modal&&<Modal close={()=>setModal(false)} create={submit}/>}</main></div>}
function Inspector({edge,node,nodes,bundleEdges,onSelectWire,editable,update,close,onSpliceUpdate,onSpliceRemove,expanded,onToggleExpanded}){return <aside className={`inspector${expanded?' inspector-expanded':''}`}><div className="inspector-head"><div><div className="eyebrow">INSPECTOR</div><h3>{edge?'Propiedades del cable':node?.type==='splice'?'Propiedades del crimp':'Componente'}</h3></div><div className="inspector-head-actions"><button className="icon-button" title={expanded?'Reducir inspector':'Expandir inspector'} aria-label={expanded?'Reducir inspector':'Expandir inspector'} onClick={onToggleExpanded}>{expanded?<Minimize2 size={15}/>:<Maximize2 size={15}/>}</button><button className="icon-button" title="Ocultar inspector" aria-label="Ocultar inspector" onClick={close}><X size={17}/></button></div></div>{edge?<>{bundleEdges?.length>1&&<div className="inspector-section inspector-bundle-section"><div className="inspector-label">CONDUCTORES DEL MAZO · {bundleEdges.length}</div><select aria-label="Conductor del mazo seleccionado" value={edge.id} onChange={event=>onSelectWire?.(event.target.value)}>{bundleEdges.map(wire=>{const source=nodes.find(item=>item.id===wire.source),target=nodes.find(item=>item.id===wire.target),signal=String(wire.data?.etiqueta||source?.data?.pinout?.[Number(wire.sourceHandle||1)-1]||`Conductor ${wire.sourceHandle||1}`).trim();return <option key={wire.id} value={wire.id}>{signal} · {source?.data?.label||wire.source}-{wire.sourceHandle||1} → {target?.data?.label||wire.target}-{wire.targetHandle||1}</option>})}</select></div>}<div className="inspector-section"><div className="inspector-label">CONEXIÓN</div><div className="connection-route"><span>{edge.source} · PIN {edge.sourceHandle||1}</span><i/><span>{edge.target} · PIN {edge.targetHandle||1}</span></div></div><div className="inspector-section"><div className="inspector-label">ESPECIFICACIÓN ELÉCTRICA</div><label className="field-label">Calibre del conductor</label><select disabled={!editable} value={edge.data.calibre||'18 AWG'} onChange={e=>update({calibre:e.target.value})}>{['10 AWG','12 AWG','14 AWG','16 AWG','18 AWG','20 AWG','22 AWG','24 AWG'].map(x=><option key={x}>{x}</option>)}</select><label className="field-label">Color de aislamiento</label><div className="color-select"><input type="color" disabled={!editable} value={edge.data.color||'#38bdf8'} onChange={e=>update({color:e.target.value})}/>{(edge.data.color||'#38bdf8').toUpperCase()}</div><label className="field-label">Material conductor</label><select disabled={!editable} value={edge.data.material||'Cobre'} onChange={e=>update({material:e.target.value})}>{['Cobre','Cobre estañado','Aluminio'].map(x=><option key={x}>{x}</option>)}</select><label className="field-label">Etiqueta del conductor</label><input disabled={!editable} value={edge.data.etiqueta||''} onChange={e=>update({etiqueta:e.target.value})} placeholder="Ej. PWR-01"/><label className="field-label">Cable continuo / funda de este tramo</label><input disabled={!editable} value={edge.data.grupo_cable||''} onChange={e=>update({grupo_cable:e.target.value})} placeholder="Ej. NW12 · déjalo vacío si no lleva funda"/><small className="inspector-hint">Usa el mismo nombre y color en los conductores que comparten este tramo entre dos crimps o conectores. Las derivaciones quedan separadas.</small><label className="field-label">Color de la funda exterior</label><div className="color-select"><input type="color" disabled={!editable} value={edge.data.color_funda||'#59636a'} onChange={e=>update({color_funda:e.target.value})}/>{(edge.data.color_funda||'#59636a').toUpperCase()}</div><label className="field-label">Longitud de diseño (mm)</label><input type="number" min="0" step="1" disabled={!editable} value={edge.data.longitud_mm??""} onChange={e=>update({longitud_mm:e.target.value===""?null:Number(e.target.value)})} placeholder="Sin dimensión"/></div><div className="inspector-note"><Shield size={15}/>Valida calibre y protección antes del ensamblaje.</div></>:node?.type==='splice'?<><div className="inspector-section component-summary"><div className="component-large-icon"><Cable size={24}/></div><h4>Empalme / crimp</h4><span>Unión de varios conductores</span><label className="field-label">Etiqueta del crimp</label><input disabled={!editable} value={node.data.label||''} onChange={e=>onSpliceUpdate(node,e.target.value)} placeholder="CRIMP-01"/><button className="btn-quiet danger" disabled={!editable} onClick={()=>onSpliceRemove(node)}>Quitar crimp y sus tramos</button></div></>:node?<><div className="inspector-section component-summary"><div className="component-large-icon"><Cpu size={24}/></div><h4>{node.data.label}</h4><span>{node.data.tipo} · {node.data.code}</span></div><div className="inspector-section"><div className="inspector-label">PINOUT</div>{node.data.pinout.map((p,i)=><div className="pinout-row" key={p}><span>{String(i+1).padStart(2,'0')}</span>{p}</div>)}</div>{node.data.url?<a className="datasheet-btn" href={node.data.url} target="_blank" rel="noreferrer"><FileText size={15}/> Consultar datasheet <Download size={14}/></a>:<button className="datasheet-btn" disabled title="Añade una URL del datasheet en la ficha del componente"><FileText size={15}/> Sin datasheet vinculado</button>}</>:<div className="inspector-empty"><MousePointer2 size={22}/><strong>Selecciona un elemento</strong><span>Elige un cable o componente para ver sus propiedades.</span></div>}</aside>}

function CoordinateOverlay({visible,axes,coordinates,originVisible,spacing,coordinateOpacity=0.3,originOpacity=0.3}){
 const {x,y,zoom}=useViewport();
 const host=useRef(null);const [size,setSize]=useState({width:900,height:650});
 useEffect(()=>{const el=host.current?.parentElement;if(!el)return;const observer=new ResizeObserver(entries=>{const rect=entries[0]?.contentRect;if(rect)setSize({width:rect.width,height:rect.height})});observer.observe(el);return()=>observer.disconnect()},[]);
 if(!visible)return null;
 const worldStep=spacing*4,screenStep=worldStep*zoom;
 const startX=Math.floor((-x/zoom)/worldStep)*worldStep,endX=Math.ceil(((size.width-x)/zoom)/worldStep)*worldStep;
 const startY=Math.floor((-y/zoom)/worldStep)*worldStep,endY=Math.ceil(((size.height-y)/zoom)/worldStep)*worldStep;
 const vertical=[],horizontal=[];for(let wx=startX;wx<=endX;wx+=worldStep)vertical.push({world:wx,screen:wx*zoom+x});for(let wy=startY;wy<=endY;wy+=worldStep)horizontal.push({world:wy,screen:wy*zoom+y});
 return <svg ref={host} className="coordinate-overlay" aria-hidden="true" style={{'--guide-step':`${screenStep}px`}}><g className="coordinate-ticks" style={{opacity:coordinateOpacity}}>{coordinates&&vertical.map(t=><g key={`x${t.world}`}><line x1={t.screen} y1={size.height-17} x2={t.screen} y2={size.height-10}/><text x={t.screen+3} y={size.height-4}>{t.world}</text></g>)}{coordinates&&horizontal.map(t=><g key={`y${t.world}`}><line x1={10} y1={t.screen} x2={17} y2={t.screen}/><text x={20} y={t.screen-3}>{t.world}</text></g>)}</g>{axes&&<g className="coordinate-origin" style={{opacity:originOpacity}}><line x1={x} y1={0} x2={x} y2={size.height}/><line x1={0} y1={y} x2={size.width} y2={y}/></g>}{originVisible&&<g className="coordinate-origin-mark" style={{opacity:originOpacity}}><circle cx={x} cy={y} r={5}/><text x={x+8} y={y-8}>0,0</text></g>}</svg>
}

function wireColorCode(color){const value=String(color||'').toLowerCase();const map={'#ff0000':'RO','#e53935':'RO','#f44336':'RO','#0000ff':'AZ','#0066ff':'AZ','#1565c0':'AZ','#00aaff':'AZ','#000000':'NE','#111111':'NE','#ffffff':'BL','#f5f5f5':'BL','#00aa00':'VE','#008000':'VE','#ffff00':'AM','#ffeb3b':'AM','#ff8800':'NA'};return map[value]||value.toUpperCase()||'—'}
function wirePathForPin(nodeId,pin,edges,nodes){const start=`${nodeId}:${pin}`,queue=[start],seen=new Set([start]),segments=[],destinations=[];while(queue.length){const current=queue.shift();for(const edge of edges){const a=`${edge.source}:${edge.sourceHandle||1}`,b=`${edge.target}:${edge.targetHandle||1}`;if(a!==current&&b!==current)continue;if(!segments.some(item=>item.id===edge.id))segments.push(edge);const next=a===current?b:a;if(seen.has(next))continue;seen.add(next);const [ownerId,ownerPin]=next.split(':');const owner=nodes.find(item=>item.id===ownerId);if(owner?.type==='splice')queue.push(next);else if(owner?.type==='component'&&ownerId!==String(nodeId))destinations.push(`${owner.data.label} · pin ${ownerPin}`)}}return{segments,destinations:[...new Set(destinations)]}}
function HarnessDistributionEditor({nodes,edges,distribution,draft,setDraft,canEdit,onSave,onClose}){const connectors=nodes.filter(node=>node.type==='component');const[selectedId,setSelectedId]=useState(connectors[0]?.id||'');const connector=connectors.find(node=>node.id===selectedId);const rows=(connector?.data.pinout||[]).map((signal,index)=>{const pin=index+1,key=String(pin),manual=draft[connector.id]?.[key]||{},path=wirePathForPin(connector.id,pin,edges,nodes),segments=path.segments,wire=segments[0],cable=segments.find(item=>item.data?.grupo_cable)?.data?.grupo_cable||segments.find(item=>item.data?.etiqueta)?.data?.etiqueta||'',awg=wire?.data?.calibre||'',color=wireColorCode(wire?.data?.color);return{pin,key,signal:manual.descripcion??signal??'',cable:manual.cable??cable,awg:manual.awg??awg,color:manual.color??color,destination:path.destinations.join(', ')}});const update=(pin,field,value)=>setDraft(current=>({...current,[connector.id]:{...(current[connector.id]||{}),[String(pin)]:{...(current[connector.id]?.[String(pin)]||{}),[field]:value}}}));const exportCsv=()=>{const rowsCsv=[['PIN','DESCRIPCIÓN','CABLE','AWG','COLOR'],...rows.map(row=>[row.pin,row.signal,row.cable,row.awg,row.color])];const csv='\ufeff'+rowsCsv.map(row=>row.map(value=>`"${String(value??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`${(connector?.data.label||'distribucion').replace(/[^\w-]+/g,'_')}-distribucion.csv`;link.click();URL.revokeObjectURL(url)};return <div className="modal-backdrop distribution-backdrop" onMouseDown={event=>event.target===event.currentTarget&&onClose()}><section className="distribution-editor-modal"><header className="distribution-editor-head"><div><div className="eyebrow">DOCUMENTACIÓN DEL ARNÉS · PIN A PIN</div><h2>Tabla de distribución</h2><p>Se prellenan señal, cable, calibre y color desde el pinout y los tramos. Los campos siguen editables.</p></div><button className="icon-button" aria-label="Cerrar tabla" onClick={onClose}><X size={17}/></button></header>{!connectors.length?<div className="distribution-empty"><Table2 size={24}/><strong>Añade un conector para generar su tabla</strong><span>La tabla tendrá una fila por cada pin definido en su pinout.</span></div>:<><div className="distribution-editor-controls"><label>Conector<select value={selectedId} onChange={event=>setSelectedId(event.target.value)}>{connectors.map(node=><option key={node.id} value={node.id}>{node.data.label} · {node.data.code||node.id}</option>)}</select></label><span>{rows.length} pines · {rows.filter(row=>row.destination).length} con ruta a otro conector</span></div><div className="distribution-editor-table-wrap"><table className="distribution-editor-table"><thead><tr><th>PIN</th><th>DESCRIPCIÓN / SEÑAL</th><th>CABLE</th><th>AWG</th><th>COLOR</th></tr></thead><tbody>{rows.map(row=><tr key={row.pin}><td><b>{String(row.pin).padStart(2,'0')}</b></td><td><input aria-label={`Descripción pin ${row.pin}`} disabled={!canEdit} value={row.signal} title={row.destination?`Ruta: ${row.destination}`:'Sin destino conectado'} onChange={event=>update(row.pin,'descripcion',event.target.value)} placeholder="Señal / función"/></td><td><input aria-label={`Cable pin ${row.pin}`} disabled={!canEdit} value={row.cable} onChange={event=>update(row.pin,'cable',event.target.value)} placeholder="Cable o mazo"/></td><td><input aria-label={`AWG pin ${row.pin}`} disabled={!canEdit} value={row.awg} onChange={event=>update(row.pin,'awg',event.target.value)} placeholder="22 AWG"/></td><td><input aria-label={`Color pin ${row.pin}`} disabled={!canEdit} value={row.color} onChange={event=>update(row.pin,'color',event.target.value)} placeholder="RO / NE / BL"/></td></tr>)}</tbody></table></div><div className="distribution-editor-foot"><span>La ruta al conector opuesto aparece al pasar el cursor sobre la señal. Los pines sin cable siguen en la tabla para completar a mano.</span><div><button className="btn-quiet" onClick={exportCsv}><Download size={14}/> CSV</button><button className="btn-quiet" onClick={onClose}>Cerrar</button><button className="btn-primary" disabled={!canEdit} onClick={onSave}><Save size={14}/> Guardar tabla</button></div></div></>}</section></div>}

