export default function App(){
 const[theme,setTheme]=useState(()=>localStorage.getItem('harness-theme')||'dark'),[workspaceTab,setWorkspaceTab]=useState('inicio');
 useEffect(()=>{localStorage.setItem('harness-theme',theme)},[theme]);
 const[user,setUser]=useState(null),[users,setUsers]=useState([]),[projects,setProjects]=useState([]),[components,setComponents]=useState([]),[active,setActive]=useState(null),[activeView,setActiveView]=useState('schematic'),[loading,setLoading]=useState(true);
 const refresh=useCallback(async()=>{
  const token=storedToken();
  try{
   if(token){
    const{data:session}=await api.get('/auth/session');
    const[u,p,c]=await Promise.all([api.get('/usuarios'),api.get('/proyectos'),api.get('/componentes')]);
    setUser(session.user);setUsers(u.data);setProjects(p.data);setComponents(c.data);
    socket.auth={token};if(!socket.connected)socket.connect();
   }else{
    socket.disconnect();setUser(null);setProjects([]);setComponents([]);
    const{data}=await api.get('/usuarios');setUsers(data);
   }
  }catch(e){
   console.error(e);
   if(e.response?.status===401){localStorage.removeItem('harness-token');sessionStorage.removeItem('harness-token');localStorage.removeItem('harness-user');socket.disconnect();setUser(null);setProjects([]);setComponents([]);try{const{data}=await api.get('/usuarios');setUsers(data)}catch{setUsers([])}}
  }finally{setLoading(false)}
 },[]);
 useEffect(()=>{
  refresh();
  const created=p=>setProjects(ps=>[p,...ps.filter(x=>x.id!==p.id)]),updated=p=>setProjects(ps=>ps.map(x=>x.id===p.id?p:x)),deleted=({id})=>setProjects(ps=>ps.filter(x=>x.id!==Number(id)));
  socket.on('project:created',created);socket.on('project:updated',updated);socket.on('project:deleted',deleted);
  return()=>{socket.off('project:created',created);socket.off('project:updated',updated);socket.off('project:deleted',deleted)}
 },[refresh]);
 const login=(session,remember=false)=>{
  localStorage.removeItem('harness-token');sessionStorage.removeItem('harness-token');
  (remember?localStorage:sessionStorage).setItem('harness-token',session.token);
  localStorage.setItem('harness-user',JSON.stringify(session.user));setUser(session.user);
  socket.auth={token:session.token};socket.connect();void refresh();
 },registered=(session,remember=false)=>login(session,remember);
 const logout=async()=>{
  try{await api.post('/auth/logout')}catch{}
  localStorage.removeItem('harness-token');sessionStorage.removeItem('harness-token');localStorage.removeItem('harness-user');
  socket.disconnect();setUser(null);setActive(null);setProjects([]);setComponents([]);void refresh();
 },create=async(nombre,descripcion)=>{const{data}=await api.post('/proyectos',{nombre,descripcion});setProjects(p=>[data,...p]);return data};
 if(loading)return <div className="loading-screen"><Cable size={22}/> Iniciando Harness Lab…</div>;
 if(!user)return <LoginPage users={users} onLogin={login} onRegistered={registered}/>;
 if(active)return <Editor project={active} user={user} theme={theme} setTheme={setTheme} initialView={activeView} back={()=>{setActive(null);refresh()}} onComponents={()=>{setWorkspaceTab('biblioteca');setActive(null);refresh()}} onProjects={()=>{setWorkspaceTab('proyectos');setActive(null);refresh()}} onAssembler={()=>{setWorkspaceTab('ensamblador');setActive(null);refresh()}} onNewHarness={async()=>{setActiveView('schematic');setActive(await create('Nuevo arnés',''))}} onProfileChange={updated=>{setUser(updated);setUsers(current=>current.map(item=>item.id===updated.id?updated:item));localStorage.setItem('harness-user',JSON.stringify(updated))}}/>;
 return <Workspace user={user} users={users} projects={projects} components={components} openProject={(project,view='schematic')=>{setActiveView(view);setActive(project)}} createProject={create} logout={logout} onUsersChange={setUsers} onComponentsChange={setComponents} onProjectsChange={setProjects} onProfileChange={updated=>{setUser(updated);localStorage.setItem('harness-user',JSON.stringify(updated))}} theme={theme} setTheme={setTheme} initialTab={workspaceTab}/>;
}

